import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dashboardApi, machineApi } from '../api/client';

import SystemStatusBar from '../components/SystemStatusBar';
import FactoryDigitalTwinGrid from '../components/FactoryDigitalTwinGrid';

import {
  Sparkles,
  ArrowRight,
  Cpu,
  Layers,
  Wrench,
  BarChart3,
  FileText,
  AlertTriangle,
  Zap,
  Gauge,
  Activity,
  CheckCircle2,
  Clock,
  ShieldAlert,
  Bot,
} from 'lucide-react';

const DashboardPage = () => {
  const navigate = useNavigate();
  const [machinesList, setMachinesList] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const res = await machineApi.getAll();
      if (res && res.data && res.data.success) {
        setMachinesList(res.data.data || []);
      }
    } catch (err) {
      console.error('Failed to fetch dashboard machines:', err);
    } finally {
      setLoading(false);
    }
  };

  const quickActions = [
    { label: 'Open Digital Twin', route: '/digital-twin', icon: Cpu, color: '#2563EB', bg: '#DBEAFE' },
    { label: 'Asset Inventory', route: '/assets', icon: Layers, color: '#059669', bg: '#ECFDF5' },
    { label: 'Maintenance Center', route: '/maintenance', icon: Wrench, color: '#EA580C', bg: '#FFEDD5' },
    { label: 'Analytics', route: '/analytics', icon: BarChart3, color: '#7C3AED', bg: '#F3E8FF' },
    { label: 'Reports', route: '/reports', icon: FileText, color: '#0284C7', bg: '#E0F2FE' },
    { label: 'AI Simulator', route: '/what-if', icon: Sparkles, color: '#D97706', bg: '#FEF3C7' },
  ];

  const summaryCards = [
    {
      title: 'Production Summary',
      metric: '14,250 m',
      subtitle: 'Target: 16,000 m (89% achieved)',
      actionText: 'View Production →',
      route: '/analytics/production',
      icon: Gauge,
      accent: '#2563EB',
      bg: '#EFF6FF',
    },
    {
      title: 'Energy Overview',
      metric: '1,245 kWh',
      subtitle: 'Efficiency: Optimal Consumption',
      actionText: 'View Energy →',
      route: '/analytics/energy',
      icon: Zap,
      accent: '#059669',
      bg: '#ECFDF5',
    },
    {
      title: 'AI Fleet Health',
      metric: '96% Health',
      subtitle: 'Overall Risk Level: Minimal',
      actionText: 'View AI →',
      route: '/ai-intelligence',
      icon: Bot,
      accent: '#7C3AED',
      bg: '#F3E8FF',
    },
    {
      title: 'Maintenance Status',
      metric: '1 Scheduled Job',
      subtitle: 'Preventive Work Orders On Schedule',
      actionText: 'View Maintenance →',
      route: '/maintenance',
      icon: Wrench,
      accent: '#EA580C',
      bg: '#FFF7ED',
    },
    {
      title: 'Alert Summary',
      metric: '11 Active Alerts',
      subtitle: 'Immediate Action Required on LOOM-201',
      actionText: 'View Alerts →',
      route: '/alerts',
      icon: AlertTriangle,
      accent: '#DC2626',
      bg: '#FEF2F2',
    },
  ];

  const recentActivities = [
    { time: '12:30 PM', title: 'Machine Restarted', desc: 'LOOM-101 cleared after routine inspection', color: '#16A34A' },
    { time: '12:25 PM', title: 'Maintenance Assigned', desc: 'Work Order #WO-204 dispatched for LOOM-201', color: '#EA580C' },
    { time: '12:18 PM', title: 'Engineer Acknowledged', desc: 'Anita Desai accepted LOOM-201 maintenance order', color: '#2563EB' },
    { time: '12:14 PM', title: 'Critical Alert Generated', desc: 'High vibration anomaly flagged on LOOM-201', color: '#DC2626' },
    { time: '12:10 PM', title: 'AI Prediction Created', desc: 'Bearing fatigue predicted with 96% confidence', color: '#7C3AED' },
  ];

  return (
    <div>
      {/* 1. Dashboard Title & Subtitle */}
      <div className="page-header" style={{ marginBottom: '1.25rem' }}>
        <div className="page-title-group">
          <h1>Factory Operations Dashboard</h1>
          <p style={{ fontSize: '0.86rem', color: '#64748B', fontWeight: '600', marginTop: '2px' }}>
            Monitor production, Digital Twin status, predictive maintenance, machine health, and AI insights across the selected factory.
          </p>
        </div>
      </div>

      {/* 2. Top KPI Section (Clean Clickable Cards) */}
      <SystemStatusBar />

      {/* 3. Main 12-Column Responsive Dashboard Body */}
      {/* Row 1: Factory Digital Twin Overview (8 cols) + Quick Actions Panel (4 cols) */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
          gap: '1.25rem',
          marginBottom: '1.5rem',
          alignItems: 'stretch',
        }}
      >
        <div style={{ flex: 2, minWidth: '300px' }}>
          <FactoryDigitalTwinGrid machines={machinesList} />
        </div>

        {/* Quick Actions Panel */}
        <div
          style={{
            background: '#ffffff',
            borderRadius: '8px',
            padding: '1.25rem 1.5rem',
            border: '1px solid #E2E8F0',
            boxShadow: '0 2px 10px rgba(0, 0, 0, 0.04)',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
          }}
        >
          <div>
            <h3 style={{ fontSize: '1.05rem', fontWeight: '900', color: '#0F172A', marginBottom: '0.3rem', display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
              ⚡ Quick Actions
            </h3>
            <p style={{ fontSize: '0.76rem', color: '#64748B', fontWeight: '600', marginBottom: '1rem' }}>
              Direct access to core management & operational modules
            </p>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
              {quickActions.map((qa, idx) => {
                const Icon = qa.icon;
                return (
                  <button
                    key={idx}
                    onClick={() => navigate(qa.route)}
                    style={{
                      background: '#F8FAFC',
                      border: '1px solid #E2E8F0',
                      borderRadius: '8px',
                      padding: '0.85rem 0.75rem',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.6rem',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease',
                      textAlign: 'left',
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.background = qa.bg;
                      e.currentTarget.style.borderColor = qa.color;
                      e.currentTarget.style.transform = 'translateY(-2px)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.background = '#F8FAFC';
                      e.currentTarget.style.borderColor = '#E2E8F0';
                      e.currentTarget.style.transform = 'none';
                    }}
                  >
                    <div
                      style={{
                        width: '32px',
                        height: '32px',
                        borderRadius: '6px',
                        background: qa.bg,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: qa.color,
                        flexShrink: 0,
                      }}
                    >
                      <Icon size={16} />
                    </div>
                    <span style={{ fontSize: '0.8rem', fontWeight: '800', color: '#0F172A', lineHeight: '1.2' }}>
                      {qa.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      {/* Row 2: 5 Clean Summary Cards */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(210px, 1fr))',
          gap: '1.25rem',
          marginBottom: '1.5rem',
        }}
      >
        {summaryCards.map((sc, idx) => {
          const Icon = sc.icon;
          return (
            <div
              key={idx}
              onClick={() => navigate(sc.route)}
              style={{
                background: '#ffffff',
                borderRadius: '8px',
                padding: '1.25rem',
                border: '1px solid #E2E8F0',
                boxShadow: '0 2px 10px rgba(0, 0, 0, 0.04)',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                minHeight: '135px',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = sc.accent;
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = `0 6px 18px ${sc.accent}15`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = '#E2E8F0';
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.boxShadow = '0 2px 10px rgba(0, 0, 0, 0.04)';
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '0.78rem', fontWeight: '800', color: '#64748B' }}>{sc.title}</span>
                <div style={{ width: '28px', height: '28px', borderRadius: '6px', background: sc.bg, color: sc.accent, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <Icon size={15} />
                </div>
              </div>

              <div style={{ margin: '0.5rem 0' }}>
                <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#0F172A', fontFamily: 'Plus Jakarta Sans, sans-serif' }}>
                  {sc.metric}
                </div>
                <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '600', marginTop: '2px' }}>
                  {sc.subtitle}
                </div>
              </div>

              <div style={{ fontSize: '0.78rem', fontWeight: '800', color: sc.accent, display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                {sc.actionText}
              </div>
            </div>
          );
        })}
      </div>

      {/* Row 3: AI Recommendation Panel (Left) & Recent Activity Stream (Right) */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
          gap: '1.25rem',
          marginBottom: '1.5rem',
        }}
      >
        {/* AI Recommendation Card */}
        <div
          style={{
            background: '#ffffff',
            borderRadius: '8px',
            padding: '1.25rem 1.5rem',
            border: '1px solid #DDD6FE',
            boxShadow: '0 2px 10px rgba(0, 0, 0, 0.04)',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
          }}
        >
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
              <h3 style={{ fontSize: '1.05rem', fontWeight: '900', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
                <Bot size={18} style={{ color: '#7C3AED' }} /> AI Predictive Maintenance Recommendation
              </h3>
              <span className="badge" style={{ background: '#F3E8FF', color: '#7C3AED', fontWeight: '800', fontSize: '0.7rem' }}>
                High Priority
              </span>
            </div>

            <div style={{ background: '#FAF5FF', border: '1px solid #E9D5FF', borderRadius: '8px', padding: '1rem', marginBottom: '1rem' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.85rem', marginBottom: '0.75rem' }}>
                <div>
                  <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>TARGET MACHINE</div>
                  <div style={{ fontSize: '1rem', fontWeight: '900', color: '#7C3AED', fontFamily: 'JetBrains Mono, monospace' }}>
                    LOOM-201
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>DIAGNOSED PROBLEM</div>
                  <div style={{ fontSize: '0.95rem', fontWeight: '900', color: '#0F172A' }}>
                    Bearing Fatigue
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>AI CONFIDENCE</div>
                  <div style={{ fontSize: '0.95rem', fontWeight: '900', color: '#16A34A' }}>
                    96%
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>REMAINING USEFUL LIFE</div>
                  <div style={{ fontSize: '0.95rem', fontWeight: '900', color: '#EA580C' }}>
                    142 Hours
                  </div>
                </div>
              </div>

              <div style={{ paddingTop: '0.65rem', borderTop: '1px solid #E9D5FF' }}>
                <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>RECOMMENDED ACTION</div>
                <div style={{ fontSize: '0.85rem', fontWeight: '800', color: '#0F172A', marginTop: '2px' }}>
                  Replace Drive Shaft Bearing within 48 Hours to prevent catastrophic breakdown.
                </div>
              </div>
            </div>
          </div>

          <button
            className="btn btn-primary"
            onClick={() => navigate('/ai-intelligence')}
            style={{ width: '100%', background: '#7C3AED', borderColor: '#7C3AED', fontWeight: '800', fontSize: '0.84rem' }}
          >
            Open AI Diagnostics <ArrowRight size={15} />
          </button>
        </div>

        {/* Recent Activity Stream (Latest 5 Items) */}
        <div
          style={{
            background: '#ffffff',
            borderRadius: '8px',
            padding: '1.25rem 1.5rem',
            border: '1px solid #E2E8F0',
            boxShadow: '0 2px 10px rgba(0, 0, 0, 0.04)',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
          }}
        >
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
              <h3 style={{ fontSize: '1.05rem', fontWeight: '900', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
                <Activity size={18} style={{ color: '#2563EB' }} /> Recent Activity
              </h3>
              <span style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '700' }}>Latest 5 Events</span>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', marginBottom: '1rem' }}>
              {recentActivities.map((act, idx) => (
                <div
                  key={idx}
                  style={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    gap: '0.75rem',
                    padding: '0.5rem 0',
                    borderBottom: idx < recentActivities.length - 1 ? '1px solid #F1F5F9' : 'none',
                  }}
                >
                  <span
                    style={{
                      fontSize: '0.72rem',
                      fontWeight: '800',
                      color: '#64748B',
                      fontFamily: 'JetBrains Mono, monospace',
                      minWidth: '60px',
                      flexShrink: 0,
                    }}
                  >
                    {act.time}
                  </span>
                  <div>
                    <div style={{ fontSize: '0.84rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
                      <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: act.color }} />
                      {act.title}
                    </div>
                    <div style={{ fontSize: '0.75rem', color: '#64748B', fontWeight: '600', marginTop: '1px' }}>
                      {act.desc}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <button
            className="btn btn-secondary"
            onClick={() => navigate('/reports')}
            style={{ width: '100%', fontWeight: '800', fontSize: '0.84rem', background: '#F8FAFC' }}
          >
            View Full Timeline →
          </button>
        </div>
      </div>
    </div>
  );
};

export default DashboardPage;
